before.code:
carousel.addEventListener('touchmove', (e) => {
  trackSwipeAnalytics(e.touches[0].clientX);
}); // Compositor waits on main thread every frame

after.code:
carousel.addEventListener('touchmove', (e) => {
  trackSwipeAnalytics(e.touches[0].clientX);
}, { passive: true }); // Compositor scrolls immediately
